best_attempt.sparql:
SELECT ?mother ?motherLabel ?deathPlace ?deathPlaceLabel WHERE {
  BIND(dbr:Johanna_Magdalene_of_Hanau-Lichtenberg AS ?person)
  OPTIONAL { ?person (dbo:mother|dbp:mother|dbo:parent) ?mother . }
  OPTIONAL { ?mother (dbo:deathPlace|dbp:deathPlace) ?deathPlace . }
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER(lang(?motherLabel) = "en") }
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel . FILTER(lang(?deathPlaceLabel) = "en") }
} LIMIT 10

